// src/components/Portal/Anlagen/Reiter.js – Reiter einer Anlage als Links (?tab=), mobil horizontal scrollbar

import Link from "next/link";
import { cn } from "@/components/ui/cn";

export default function Reiter({ basis, aktiv, tabs = [], label = "Bereiche der Anlage" }) {
  return (
    <nav aria-label={label} className="-mx-4 mb-6 overflow-x-auto px-4 ov-no-scrollbar md:mx-0 md:px-0">
      <ul className="flex min-w-max gap-1.5 rounded-full bg-white p-1.5 ring-1 ring-ink-200/70 md:min-w-0 md:flex-wrap">
        {tabs.map((t) => {
          const an = t.id === aktiv;
          const Icon = t.icon;
          return (
            <li key={t.id}>
              <Link
                href={`${basis}${t.id === "uebersicht" ? "" : `?tab=${t.id}`}`}
                aria-current={an ? "page" : undefined}
                scroll={false}
                className={cn("inline-flex h-10 items-center gap-2 whitespace-nowrap rounded-full px-4 text-[14px] font-semibold transition-colors", an ? "bg-navy-900 text-white" : "text-ink-700 hover:bg-ink-50")}
              >
                {Icon && <Icon aria-hidden="true" className="h-4 w-4" />}
                {t.label}
                {t.zaehler ? <span className={cn("ov-num rounded-full px-1.5 text-[11.5px] font-bold", an ? "bg-white/20 text-white" : "bg-red-600 text-white")}>{t.zaehler}</span> : null}
              </Link>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}
import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { cn } from "./cn";

const VARIANTEN = {
  primary:
    "bg-ov-600 text-white shadow-[0_8px_24px_-8px_rgba(102,153,51,0.65)] hover:bg-ov-700 hover:shadow-[0_12px_32px_-8px_rgba(102,153,51,0.75)]",
  navy: "bg-navy-700 text-white hover:bg-navy-800 shadow-[0_8px_24px_-10px_rgba(0,52,115,0.6)]",
  secondary:
    "bg-white text-ink-900 ring-1 ring-inset ring-ink-200 hover:ring-ink-300 hover:bg-ink-50",
  ghost: "text-ink-800 hover:bg-ink-100",
  white: "bg-white text-navy-900 hover:bg-ov-50 shadow-[0_8px_30px_-10px_rgba(0,0,0,0.4)]",
  outlineLight:
    "text-white ring-1 ring-inset ring-white/35 hover:bg-white/10 hover:ring-white/60 backdrop-blur-sm",
  sun: "bg-sun-400 text-navy-950 hover:bg-sun-300 shadow-[0_10px_30px_-10px_rgba(245,167,15,0.7)]",
};

const GROESSEN = {
  sm: "h-10 px-4 text-[14px] gap-1.5 rounded-full",
  md: "h-12 px-6 text-[15px] gap-2 rounded-full",
  lg: "h-14 px-8 text-[16px] gap-2.5 rounded-full",
};

/**
 * Einheitlicher Button. Mit `href` wird ein Link gerendert (intern via
 * next/link, extern/tel/mailto als <a>), sonst ein <button>.
 */
export default function Button({
  href,
  variant = "primary",
  size = "md",
  pfeil = false,
  icon: Icon,
  className,
  children,
  ...rest
}) {
  const klassen = cn(
    "group relative inline-flex select-none items-center justify-center whitespace-nowrap font-semibold tracking-[-0.005em] transition-all duration-300 active:scale-[0.98] disabled:opacity-50",
    VARIANTEN[variant],
"use client";

// Einladung in eine Organisation annehmen (angemeldet mit der eingeladenen E-Mail-Adresse).

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Check, Loader2 } from "lucide-react";
import { senden } from "@/lib/plattform/client";
import { FehlerBox } from "@/components/Portal/felder";

export default function EinladungAnnehmen({ token }) {
  const router = useRouter();
  const [laeuft, setLaeuft] = useState(false);
  const [fehler, setFehler] = useState("");
  return (
    <div className="space-y-4">
      <FehlerBox>{fehler}</FehlerBox>
      <button
        type="button"
        disabled={laeuft}
        onClick={async () => {
          setLaeuft(true);
          setFehler("");
          try {
            const r = await senden("/api/portal/organisation/einladung", { body: { token } });
            router.replace(`/portal/organisation?id=${r.organisationId}`);
            router.refresh();
          } catch (e) {
            setFehler(e.message);
            setLaeuft(false);
          }
        }}
        className="inline-flex h-12 w-full items-center justify-center gap-2 rounded-full bg-ov-600 px-6 text-[15px] font-semibold text-white shadow-[0_8px_24px_-8px_rgba(102,153,51,0.65)] transition-colors hover:bg-ov-700 disabled:opacity-60"
      >
        {laeuft ? <Loader2 aria-hidden="true" className="h-4 w-4 animate-spin" /> : <Check aria-hidden="true" className="h-4 w-4" />}
        Einladung annehmen
      </button>
    </div>
  );
}

